-- Venue Live Guest "Lamaran Musim Gugur". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara autumn), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'autumn', 'Lamaran Musim Gugur', 'autumn', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 158, 'center 38%',
  $t${"name":"Lamaran Musim Gugur","orn":"diamond","ui":{"ivory":"#FFF7EE","white":"#FFFFFF","soft":"#F6DFC4","soft2":"#E0A15F","accent":"#B5532A","deep":"#5A2E1A","ink":"#4A2A1C","mute":"#9A7A66","line":"#EFD9BF","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFFAF3","ink":"#4A2A1C","accent":"#B5532A","gold":"#D9A93F","leaf":"#F6DFC4","hbg":"rgba(255,247,238,.94)","hline":"#D9A93F","motif":"diamond"},"hud":{"bg":"rgba(90,46,26,.9)","acc":"#F2D27A","on":"#5A2E1A"},"scr":{"wine":"#8E2F2F","veil":"255,247,238"}}$t$::jsonb
